<script setup>
import { ref, computed, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import Chart from 'chart.js/auto'
import ExcelJS from 'exceljs'
const title=ref('各班平均成績'), xTitle=ref('班級'), yTitle=ref('分數'), color=ref('#ea8c28'), horizontal=ref(false), stacked=ref(false), legend=ref(true), zero=ref(true)
const input=ref('班級,期中,期末\n資管一甲,78,86\n資管二甲,85,91\n資管三甲,82,94\n資管四甲,90,96')
const canvas=ref(null), error=ref(''), book=ref(null), sheets=ref([]), selected=ref(''), busy=ref(false), status=ref('')
let chart=null
function parse(text){
 const rows=[];let row=[],field='',quoted=false
 text=text.replace(/^\uFEFF/,'')
 for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"'&&!field)quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);rows.push(row);row=[];field=''}else field+=c}
 if(quoted)throw Error('CSV 引號尚未關閉');row.push(field);rows.push(row);return rows.filter(r=>r.some(v=>v.trim()!==''))
}
const parsed=computed(()=>{try{const rows=parse(input.value);if(rows.length<2||rows[0].length<2)throw Error('請提供標題列、分類欄及至少一組數值資料。');const header=rows[0];if(header.length>13||rows.length>501)throw Error('最多 12 組數值、500 筆分類。');const labels=[],series=header.slice(1).map((s,i)=>({label:s.trim()||`數列 ${i+1}`,data:[]}));for(const [i,r] of rows.slice(1).entries()){if(r.length!==header.length)throw Error(`第 ${i+2} 列欄位數不一致`);labels.push(r[0]);r.slice(1).forEach((v,j)=>{const n=v.trim()===''?null:Number(v);if(n!==null&&!Number.isFinite(n))throw Error(`第 ${i+2} 列「${series[j].label}」不是數值`);series[j].data.push(n)})}return {labels,series,error:''}}catch(e){return {labels:[],series:[],error:e.message}}})
const palette=['#2499c2','#8b5cf6','#10b981','#e85d75','#64748b','#eab308']
function render(){if(chart){chart.destroy();chart=null}if(!canvas.value||parsed.value.error)return;chart=new Chart(canvas.value,{type:'bar',data:{labels:parsed.value.labels,datasets:parsed.value.series.map((s,i)=>({...s,backgroundColor:i===0?color.value:palette[(i-1)%palette.length],borderRadius:5}))},options:{responsive:true,maintainAspectRatio:false,indexAxis:horizontal.value?'y':'x',animation:false,plugins:{title:{display:!!title.value,text:title.value,font:{size:18}},legend:{display:legend.value}},scales:{x:{stacked:stacked.value,title:{display:true,text:horizontal.value?yTitle.value:xTitle.value},...(horizontal.value?{beginAtZero:zero.value}:{})},y:{stacked:stacked.value,title:{display:true,text:horizontal.value?xTitle.value:yTitle.value},...(!horizontal.value?{beginAtZero:zero.value}:{})}}}})}
watch([parsed,title,xTitle,yTitle,color,horizontal,stacked,legend,zero],()=>nextTick(render),{flush:'post'})
onMounted(render);onBeforeUnmount(()=>chart?.destroy())
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function cellValue(cell){const v=cell.value;if(v==null)return '';if(typeof v==='object'&&'formula' in v||typeof v==='object'&&'sharedFormula' in v)return v.result??'';if(v instanceof Date)return cell.text;return typeof v==='number'?v:cell.text}
function importSheet(){try{error.value='';const ws=book.value?.getWorksheet(Number(selected.value));if(!ws)return;if(ws.rowCount>501||ws.columnCount>13)throw Error('工作表最多 501 列、13 欄，請先裁減資料。');const rows=[];for(let i=1;i<=ws.rowCount;i++){const r=[];for(let j=1;j<=ws.columnCount;j++)r.push(csvCell(cellValue(ws.getRow(i).getCell(j))));rows.push(r.join(','))}input.value=rows.join('\n');status.value='已匯入 '+ws.name}catch(e){error.value=e.message}}
async function upload(e){const f=e.target.files?.[0];if(!f)return;busy.value=true;error.value='';status.value='';try{if(f.size>10*1024*1024)throw Error('檔案上限 10 MB');if(/\.xlsx$/i.test(f.name)){const wb=new ExcelJS.Workbook();await wb.xlsx.load(await f.arrayBuffer());book.value=wb;sheets.value=wb.worksheets.map(w=>({id:w.id,name:w.name}));selected.value=sheets.value[0]?.id??'';importSheet()}else if(/\.(csv|txt)$/i.test(f.name)){book.value=null;sheets.value=[];input.value=await f.text();status.value='已匯入 '+f.name}else throw Error('請選擇 XLSX、CSV 或 TXT')}catch(e){error.value=e.message+(/sheets/.test(e.message)?'；請以 Excel 另存標準 XLSX，或改用 UTF-8 CSV。':'')}finally{busy.value=false;e.target.value=''}}
function download(){if(!chart)return;const c=document.createElement('canvas');c.width=chart.canvas.width;c.height=chart.canvas.height;const ctx=c.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(chart.canvas,0,0);const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='SkillIsland-bar.png';a.click()}
function sample(){input.value='班級,期中,期末\n資管一甲,78,86\n資管二甲,85,91\n資管三甲,82,94\n資管四甲,90,96';error.value='';status.value=''}
</script>
<template>
<section class="bar-lab">
 <header><small>DATA LAB / V6.0</small><h3>📊 長條圖工作室</h3><p>匯入資料、自訂圖表、立即預覽與下載。</p></header>
 <div class="lab-grid"><article><h4>① 資料來源</h4><div class="actions"><button @click="sample">載入範例</button><label class="upload">上傳 Excel / CSV<input type="file" accept=".xlsx,.csv,.txt" @change="upload" :disabled="busy"></label></div><label v-if="sheets.length">工作表<select v-model="selected" @change="importSheet"><option v-for="s in sheets" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p v-if="status">{{status}}</p><label>CSV 資料（首列為欄名、首欄為分類）<textarea v-model="input" rows="10" spellcheck="false"/></label><p v-if="busy">讀取中…</p><p v-if="error || parsed.error" class="err" role="alert">{{error || parsed.error}}</p></article>
 <article><h4>② 圖表設定</h4><label>圖表標題<input v-model="title"></label><label>分類軸標題<input v-model="xTitle"></label><label>數值軸標題<input v-model="yTitle"></label><label>第一組數列顏色<input type="color" v-model="color"></label><div class="checks"><label><input type="checkbox" v-model="horizontal"> 橫向長條圖</label><label><input type="checkbox" v-model="stacked"> 堆疊模式</label><label><input type="checkbox" v-model="legend"> 顯示圖例</label><label><input type="checkbox" v-model="zero"> 數值軸從零開始</label></div></article></div>
 <article><div class="actions between"><h4>③ 即時圖表預覽</h4><button @click="download" :disabled="!!parsed.error">下載 PNG</button></div><p>{{parsed.labels.length}} 個分類 · {{parsed.series.length}} 組數列</p><div class="chart-area"><canvas ref="canvas" aria-label="長條圖"></canvas></div></article>
 <article v-if="!parsed.error"><h4>資料預覽（前 20 筆）</h4><div class="table-wrap"><table><thead><tr><th>分類</th><th v-for="(s,i) in parsed.series" :key="i">{{s.label}}</th></tr></thead><tbody><tr v-for="(l,i) in parsed.labels.slice(0,20)" :key="i"><td>{{l}}</td><td v-for="(s,j) in parsed.series" :key="j">{{s.data[i] ?? '—'}}</td></tr></tbody></table></div></article>
</section>
</template>
<style scoped>
.bar-lab{display:grid;gap:16px;color:#28364a}.bar-lab header{background:linear-gradient(115deg,#ffedd5,#fef3c7);padding:24px;border-radius:22px;color:#92400e}.bar-lab header small{letter-spacing:2px;font-weight:800}.bar-lab h3{font-size:28px;margin:8px 0}.bar-lab p{margin:8px 0}.lab-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:16px}.bar-lab article{background:white;border:1px solid #e2e8f0;border-radius:20px;padding:18px;min-width:0}.bar-lab h4{font-weight:800;color:#9a3412;margin:0 0 12px}.bar-lab label{display:grid;gap:6px;margin:9px 0;font-weight:600}.bar-lab input:not([type=checkbox]),.bar-lab select,.bar-lab textarea{width:100%;border:1px solid #cbd5e1;border-radius:9px;padding:9px;background:white;color:#243447}.bar-lab textarea{font-family:monospace;resize:vertical}.bar-lab input[type=color]{height:42px}.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.actions.between{justify-content:space-between}.bar-lab .upload{display:inline-block;padding:10px 14px;background:#ffedd5;border-radius:12px;cursor:pointer}.upload input{display:none}.checks{display:grid;grid-template-columns:1fr 1fr}.checks label{display:flex;align-items:center}.chart-area{height:390px;position:relative}.err{color:#b91c1c}.table-wrap{overflow:auto}.bar-lab table{width:100%;border-collapse:collapse}.bar-lab td,.bar-lab th{padding:9px;text-align:left;border-bottom:1px solid #e2e8f0}.bar-lab th{background:#fff7ed}.bar-lab button:disabled{opacity:.5}@media(max-width:800px){.lab-grid{grid-template-columns:1fr}.chart-area{height:300px}}
</style>
